"""TypeScript emitter: vocabulary unions + parsers, wire interfaces."""
from __future__ import annotations

import json

from schema_model import Model, Type, pascal

HEADER = """// @generated by packages/schemas/codegen/gen.py from packages/schemas/vocabulary.json and
// packages/schemas/json/*.schema.json. Do not edit; run `bash packages/schemas/codegen/gen.sh`.
"""


def doc(text: str, indent: str = "") -> str:
    lines = [l.rstrip() for l in text.strip().splitlines()]
    if not lines:
        return ""
    body = "".join(f"{indent} * {l}\n" if l else f"{indent} *\n" for l in lines)
    return f"{indent}/**\n{body}{indent} */\n"


def ts_type(t: Type) -> str:
    if t.kind == "string":
        base = "string"
    elif t.kind in ("integer", "number"):
        base = "number"
    elif t.kind == "boolean":
        base = "boolean"
    elif t.kind == "any":
        return "unknown"
    elif t.kind == "array":
        inner = ts_type(t.item)
        base = f"({inner})[]" if "|" in inner else f"{inner}[]"
    elif t.kind == "map":
        base = f"Record<string, {ts_type(t.item)}>"
    elif t.kind == "ref":
        base = t.name
    elif t.kind == "enum":
        base = pascal(t.name)
    else:
        raise AssertionError(t.kind)
    return f"{base} | null" if t.nullable else base


def emit_vocabulary(model: Model) -> str:
    out = [HEADER, f'\n/** Version of packages/schemas/vocabulary.json these unions were generated from. */\nexport const VOCABULARY_VERSION = "{model.vocabulary_version}";\n']
    for axis in model.axes.values():
        name = pascal(axis.id)
        codes = ", ".join(json.dumps(v["code"]) for v in axis.values)
        out.append("\n" + doc(f"{axis.name_ko}: {axis.concept_ko}\n\nAxis `{axis.id}`."))
        out.append(f"export const {name} = [{codes}] as const;\n")
        out.append(f"export type {name} = (typeof {name})[number];\n")
        out.append(
            f"/** Throws on an unknown value: unknown states are never treated as a success. */\n"
            f"export function parse{name}(value: unknown): {name} {{\n"
            f"  if (typeof value === \"string\" && ({name} as readonly string[]).includes(value)) {{\n"
            f"    return value as {name};\n  }}\n"
            f"  throw new Error(`unknown {axis.id}: ${{JSON.stringify(value)}}`);\n}}\n"
        )
    return "".join(out)


def used_axes(model: Model) -> set:
    found = set()

    def walk(t: Type):
        if t.kind == "enum":
            found.add(t.name)
        if t.item is not None:
            walk(t.item)

    for st in model.structs.values():
        for f in st.fields:
            walk(f.type)
    return found


def emit_types(model: Model, structs=None, imports: str | None = None, header: str = HEADER) -> str:
    """`structs`/`imports`/`header` let emit_api reuse this for the API client."""
    if imports is None:
        enums = sorted({pascal(a) for a in used_axes(model)})
        imports = "\nimport type {\n" + "".join(f"  {e},\n" for e in enums) + '} from "./vocabulary";\n'
    out = [header, imports]
    for st in (model.structs.values() if structs is None else structs):
        out.append("\n" + doc(st.description or st.name))
        out.append(f"export interface {st.name} {{\n")
        for f in st.fields:
            if f.description:
                out.append(doc(f.description, "  "))
            q = "" if f.required else "?"
            out.append(f"  {f.name}{q}: {ts_type(f.type)};\n")
        out.append("}\n")
    return "".join(out)


def emit_index() -> str:
    return HEADER + 'export * from "./vocabulary";\nexport * from "./types";\n'


def emit_tsconfig() -> str:
    cfg = {
        "compilerOptions": {
            "target": "ES2020", "module": "ES2020", "moduleResolution": "Bundler", "strict": True,
            "noUnusedLocals": True, "noEmit": True, "skipLibCheck": False, "types": [],
        },
        "files": ["index.ts", "vocabulary.ts", "types.ts"],
    }
    return json.dumps(cfg, indent=2) + "\n"


def emit_package_json(version: str) -> str:
    pkg = {"name": "onjeon-contracts", "version": version, "private": True, "description": "Generated ONJEON contract types", "types": "index.ts"}
    return json.dumps(pkg, indent=2) + "\n"


def emit(model: Model, version: str) -> dict:
    return {
        "vocabulary.ts": emit_vocabulary(model),
        "types.ts": emit_types(model),
        "index.ts": emit_index(),
        "tsconfig.json": emit_tsconfig(),
        "package.json": emit_package_json(version),
    }
